func (q *Queries) StartExcludeRecompute(ctx context.Context, id int64) (int64, error) {
	row := q.db.QueryRow(ctx, startExcludeRecompute, id)
	var exclude_gen int64
	err := row.Scan(&exclude_gen)
	return exclude_gen, err
}
